    private void btnloginActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnloginActionPerformed
       
      
       
       String uname; // admin
       String pword; //admin123
      
       
       uname=txtunamebox.getText();      // Cafe Manager
       pword=pwordbox.getText();

       
       
       if(uname.equals("admin") && pword.equals("admin123")){
           
          JOptionPane.showMessageDialog(this,"Cafe Manager Login Successful");
          
           
           ManagerView m1=new ManagerView();
           m1.setVisible(true);              // Link ManagerView Login
           this.dispose();  //Hide LoginView
           
           
           
           }else if(uname.equals("barista") && pword.equals("barista123")){
              JOptionPane.showMessageDialog(null,"Barista login Successful"); 
              
              BaristaView b1=new BaristaView();
              b1.setVisible(true);
              this.dispose();

           }else{
             
              JOptionPane.showMessageDialog(null,"Username or Password incorrect");
        
           }  
    }//GEN-LAST:event_btnloginActionPerformed

